fn solve(x: i32) -> i32 {
    // Convert the number to string to inspect its first digit and length.
    let s = x.to_string();
    
    // The digit d is the first (and only) character of the string, parsed as an integer.
    let d = s.chars()
             .next()
             .unwrap()
             .to_digit(10)
             .unwrap() as i32;
    
    // k is the number of times the digit is repeated, i.e., the length of the string.
    let k = s.len() as i32;
    
    // For each digit less than d, we type lengths 1, 2, 3, 4 => 1+2+3+4 = 10 presses.
    // So those contribute (d - 1) * 10 presses in total.
    //
    // For digit d itself, up to length k, we need 1 + 2 + ... + k presses,
    // which is k * (k + 1) / 2.
    //
    // Summing these gives the total score.
    (d - 1) * 10 + k * (k + 1) / 2
}